package net.officefloor.hq.app.claim;

import jakarta.servlet.http.HttpServletRequest;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonNotFoundException;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.role.RoleRepository;
import net.officefloor.hq.app.setting.SettingsRepository;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/**
 * Moves a DRAFT, OPEN or PENDING claim to another person on the sheet. Only a role the permission matrix
 * allows (by the standing rule, a steward) may move it.
 * It keeps its number and date, loses any figure a statement bound it to, and is listed as its new
 * person's newest claim.
 */
public class ReassignClaim {
    public void apply(@Val Sheet sheet, @Val Claim claim, @Val ReassignRequest reassign, PersonRepository people,
            RoleRepository roles, SettingsRepository settings, HttpServletRequest request, Out<Reassignment> reassignmentOut)
            throws InvalidClaimStatusException, ApprovalException, PersonNotFoundException, InvalidClaimException {
        String user = Audit.user(request);
        String role = roles.roleOf(sheet.id(), user);
        if (!settings.find(sheet.id()).allows("reassign", role)) {
            throw new ApprovalException("A " + role + " may not move a claim: " + user + " is a " + role);
        }
        Person to = null;
        try {
            to = people.find(sheet.id(), Long.parseLong(reassign.personId()));
        } catch (NumberFormatException e) {
            // not an id: not found
        }
        if (to == null) throw new PersonNotFoundException(reassign.personId());
        if (to.getId() == claim.getPersonId()) {
            throw new InvalidClaimException("The claim is already " + to.getName() + "'s");
        }
        Person from = people.find(sheet.id(), claim.getPersonId());
        claim.reassign(to.getId());
        reassignmentOut.set(new Reassignment(from.getName(), to.getName()));
    }
}
# Move a DRAFT, OPEN or PENDING claim to another person on the sheet (a steward). A settled or
# voided claim, a clerk, or a person not on the sheet is refused and writes nothing.
# A viewer may change nothing: refused before anything is read or written.
viewer:
  class: net.officefloor.hq.app.role.CheckCanChange
  next: validate
validate:
  class: net.officefloor.hq.app.claim.ValidateReassign
  govern: [ transaction ]
  next: loadSheet
loadSheet:
  class: net.officefloor.hq.app.sheet.LoadSheet
  govern: [ transaction ]
  next: before
# The sheet's figures before the change, so the rollup lines tell which moved.
before:
  class: net.officefloor.hq.app.rollup.TakeRollup
  govern: [ transaction ]
  next: load
load:
  class: net.officefloor.hq.app.claim.LoadClaim
  govern: [ transaction ]
  next: closed
# A claim due by a date inside a closed period is a 409 and writes nothing.
closed:
  class: net.officefloor.hq.app.period.CheckClaimPeriod
  govern: [ transaction ]
  next: apply
apply:
  class: net.officefloor.hq.app.claim.ReassignClaim
  govern: [ transaction ]
  next: retired
# A claim dated after its new person's retirement is refused and writes nothing.
retired:
  class: net.officefloor.hq.app.person.CheckClaimRetired
  govern: [ transaction ]
  next: save
save:
  class: net.officefloor.hq.app.claim.SaveClaim
  govern: [ transaction ]
  next: audit
# Last before the response: every rule has passed and the change is saved.
audit:
  class: net.officefloor.hq.app.claim.AuditClaimReassigned
  govern: [ transaction ]
  next: rollup
# After the change's own lines: the figures it moved.
rollup:
  class: net.officefloor.hq.app.rollup.AuditRollup
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.claim.RespondWithClaim
  govern: [ transaction ]
